"""Golden daily-target fixtures (Plan 10 Task 6): packages/test-fixtures/targets.

The expected files are generated by scripts/generate_target_expectations.py from the real
engine and the API's own mapping. The goldens below are the hand-checked numbers of the spec's
worked examples (section 4.12), so a generator bug cannot bless a wrong number."""

import json
import re
import subprocess
import sys
from pathlib import Path

from app.scoring import targets
from scripts import generate_target_expectations as gen
from tests.fixtures.loader import FIXTURES

TARGETS = FIXTURES / "targets"
INPUTS = TARGETS / "inputs"
EXPECTED = TARGETS / "expected"
MESSAGES = Path(__file__).resolve().parents[4] / "packages" / "i18n" / "messages"
API_DIR = Path(__file__).resolve().parents[2]


def _expected(stem: str) -> dict:
    return json.loads((EXPECTED / f"{stem}.json").read_text(encoding="utf-8"))


def test_expectations_are_current():
    """CI fails if stale: `uv run python scripts/generate_target_expectations.py --write`,
    then review with nutrition-safety-reviewer; never edit an expected file by hand."""
    done = subprocess.run(
        [sys.executable, "scripts/generate_target_expectations.py", "--check"],
        cwd=API_DIR,
        capture_output=True,
        text=True,
        check=False,
    )
    assert done.returncode == 0, done.stdout + done.stderr


def test_every_input_has_expected():
    inputs = {p.name for p in INPUTS.glob("*.json")}
    expected = {p.name for p in EXPECTED.glob("*.json")}
    assert inputs and inputs == expected
    for name in inputs:
        case = json.loads((INPUTS / name).read_text(encoding="utf-8"))
        assert set(case) == {"as_of", "stored", "body", "settings"}, name
        assert set(case["body"]) == {
            "age",
            "sex",
            "height_cm",
            "weight_kg",
            "body_fat_pct",
            "goal",
        }, name


def test_the_planned_cases_exist():
    stems = {p.stem for p in INPUTS.glob("*.json")}
    planned = {
        "g1_build_muscle", "g2_lose_adjusted", "g3_eat_healthy", "g4_floor", "g5_taper",
        "g8_sex_other", "g11_lean_mass", "g12_lean_mass_bmi30", "g6_minor",
        "g7_underweight_lose", "floor_male", "floor_average", "floor_limits_deficit",
        "rate_max_kg", "deficit_1000", "taper_band", "taper_past", "protein_cap_energy",
        "bmi_29_9", "bmi_30_0", "body_fat_3", "body_fat_70", "body_fat_2_9", "body_fat_70_1",
        "body_fat_blank", "devine_male", "devine_female", "devine_average", "devine_short",
        "age_18", "age_78", "age_79", "needs_birth_year", "needs_sex", "needs_height_cm",
        "needs_weight_kg", "pregnancy", "underweight_at_read", "none", "g1_hide_energy",
        "g1_hide_all", "g4_hide_all", "floor_other_female",
    }  # fmt: skip
    planned |= {
        f"activity_{lv}_{sx}"
        for lv in ("sedentary", "light", "moderate", "very")
        for sx in ("male", "female")
    }
    planned |= {
        f"lean_factor_{g}"
        for g in ("build_muscle", "weight_loss", "healthy_eating", "weight_gain", "none")
    }
    assert planned <= stems, sorted(planned - stems)


def test_hand_checked_goldens():
    def macros(stem):
        t = _expected(stem)
        return (t["energy_kcal"], t["protein_g"], t["fat_g"], t["carbs_g"])

    assert macros("g1_build_muscle") == (2760, 112, 77, 405)
    g2 = _expected("g2_lose_adjusted")
    assert (g2["energy_kcal"], g2["protein_g"], g2["fat_g"], g2["carbs_g"]) == (1540, 71, 43, 217)
    assert g2["explanation"]["protein_basis"] == "adjusted_weight"
    assert g2["explanation"]["ibw_kg"] == 52.4
    assert macros("g3_eat_healthy") == (1450, 46, 40, 227)
    g4 = _expected("g4_floor")
    assert (g4["energy_kcal"], g4["protein_g"], g4["fat_g"], g4["carbs_g"]) == (1200, 62, 33, 164)
    assert g4["flags"] == ["deficit_capped", "floor_applied"]
    g5 = _expected("g5_taper")
    assert (g5["energy_kcal"], g5["protein_g"], g5["fat_g"], g5["carbs_g"]) == (1940, 91, 54, 273)
    assert g5["rate"]["kg_per_week"] == 0.3 and g5["flags"] == ["taper_active"]
    assert macros("g8_sex_other") == (2180, 50, 61, 358)
    other = _expected("floor_other_female")  # Q11b: sex "other" + female estimate -> floor 1500
    assert other["energy_kcal"] == 1500 and other["explanation"]["floor_kcal"] == 1500
    assert "floor_applied" in other["flags"]
    g11, g12 = _expected("g11_lean_mass"), _expected("g12_lean_mass_bmi30")
    assert (g11["protein_g"], g11["carbs_g"]) == (119, 398)
    assert (g12["protein_g"], g12["carbs_g"]) == (74, 214)
    assert g11["explanation"]["protein_basis"] == g12["explanation"]["protein_basis"] == "lean_mass"


def test_statuses_errors_and_flags_are_pinned():
    assert _expected("g6_minor")["status"] == "not_available_minor"
    assert _expected("g6_minor")["energy_kcal"] is None
    assert _expected("g7_underweight_lose")["error"]["code"] == "goal_not_allowed_underweight"
    assert _expected("pregnancy")["status"] == "paused_pregnancy"
    assert _expected("none")["status"] == "none"
    for field, stem in (
        ("birth_year", "needs_birth_year"),
        ("sex", "needs_sex"),
        ("height_cm", "needs_height_cm"),
        ("weight_kg", "needs_weight_kg"),
    ):
        t = _expected(stem)
        assert t["status"] == "needs_body_data" and t["missing_fields"] == [field]
    for stem in ("body_fat_2_9", "body_fat_70_1"):
        assert _expected(stem)["error"] == {
            "code": "body_fat_out_of_range",
            "details": {"max": 70, "min": 3},
        }
    for stem in ("body_fat_3", "body_fat_70"):
        assert _expected(stem)["explanation"]["protein_basis"] == "lean_mass"
    assert _expected("body_fat_blank")["explanation"]["protein_basis"] == "actual_weight"
    assert _expected("bmi_29_9")["explanation"]["protein_basis"] == "actual_weight"
    assert _expected("bmi_30_0")["explanation"]["protein_basis"] == "adjusted_weight"
    assert "outside_equation_age_range" in _expected("age_79")["flags"]
    assert "outside_equation_age_range" not in _expected("age_78")["flags"]
    assert "floor_limits_deficit" in _expected("floor_limits_deficit")["flags"]
    assert "floor_applied" not in _expected("floor_limits_deficit")["flags"]
    assert "goal_weight_reached" in _expected("taper_band")["flags"]
    assert "goal_weight_reached" in _expected("taper_past")["flags"]
    assert "protein_capped" in _expected("protein_cap_energy")["flags"]
    assert {"rate_capped", "deficit_capped"} <= set(_expected("deficit_1000")["flags"])
    under = _expected("underweight_at_read")
    assert under["direction"] == "maintain" and "underweight_maintenance" in under["flags"]
    for stem, kg in (
        ("devine_male", 70.5),
        ("devine_female", 66.0),
        ("devine_average", 68.2),
        ("devine_short", 45.5),
    ):
        assert _expected(stem)["explanation"]["ibw_kg"] == kg, stem
    factors = {
        "build_muscle": 2.0,
        "weight_loss": 1.5,
        "healthy_eating": 1.0,
        "weight_gain": 1.0,
        "none": 1.0,
    }
    for goal, factor in factors.items():
        assert _expected(f"lean_factor_{goal}")["explanation"]["protein_g_per_kg"] == factor
    for level, factor in (
        ("sedentary", 1.2),
        ("light", 1.375),
        ("moderate", 1.55),
        ("very", 1.725),
    ):
        for sex in ("male", "female"):
            assert _expected(f"activity_{level}_{sex}")["explanation"]["activity_factor"] == factor


def test_hidden_number_fixtures_carry_no_hidden_digit():
    g1 = _expected("g1_build_muscle")
    energy = _expected("g1_hide_energy")
    assert energy["numbers_hidden"] == {"energy": True, "macros": False}
    assert energy["energy_kcal"] is None and energy["protein_g"] == g1["protein_g"]
    assert (
        energy["explanation"]["bmr_kcal"] is None
        and energy["explanation"]["activity_factor"] == 1.55
    )
    for stem in ("g1_hide_all", "g4_hide_all"):
        t = _expected(stem)
        assert t["numbers_hidden"] == {"energy": True, "macros": True}
        for key in ("energy_kcal", "protein_g", "fat_g", "carbs_g"):
            assert t[key] is None, (stem, key)
        assert {k for k, v in t["explanation"].items() if v is not None} == {"protein_basis"}
        assert t["rate"] is not None and t["rate_options"]  # the pace stays visible
        # ... as a percent only (kg/week would reveal the body weight)
        assert t["rate"]["pct_bw_per_week"] and t["rate"]["kg_per_week"] is None
        assert all(o["kg_per_week"] is None and o["pct_bw_per_week"] for o in t["rate_options"])
    assert "floor_applied" in _expected("g4_hide_all")["flags"]  # the client shows the hidden copy


def test_direction_defaults_match_api():
    data = json.loads((TARGETS / "direction_defaults.json").read_text(encoding="utf-8"))
    assert set(data) == {"build_muscle", "weight_loss", "healthy_eating", "weight_gain", "none"}
    for goal, direction in data.items():
        assert targets.default_direction(None if goal == "none" else goal) == direction


def _en_hi_mr(key: str):
    for lang in ("en", "hi", "mr"):
        node = json.loads((MESSAGES / f"{lang}.json").read_text(encoding="utf-8"))
        for part in key.split("."):
            node = node.get(part) if isinstance(node, dict) else None
            if node is None:
                break
        yield lang, node


def test_every_flag_has_copy():
    for flag in (*targets.FLAG_ORDER, "floor_applied_hidden", "carbs_below_reference_hidden"):
        for lang, value in _en_hi_mr(f"targets.flag.{flag}"):
            assert isinstance(value, str) and value, (lang, flag)


def test_hidden_variants_carry_no_number_and_field_names_exist():
    for lang, value in _en_hi_mr("targets.flag.carbs_below_reference_hidden"):
        assert not re.search(r"\d", value), (lang, value)
    for lang, value in _en_hi_mr("targets.flag.rate_capped"):
        assert "safest" not in value.lower(), (lang, value)
    for field in ("height", "weight", "birth_year", "sex", "activity", "body_fat"):
        for lang, value in _en_hi_mr(f"targets.field.{field}"):
            assert isinstance(value, str) and value, (lang, field)
            assert "(" not in value and "kg" not in value and "cm" not in value, (lang, field)


def test_every_explanation_key_has_copy():
    for key in (
        "targets.how.title", "targets.how.bmr", "targets.how.activity", "targets.how.maintenance",
        "targets.how.adjustment", "targets.how.protein", "targets.how.protein_adjusted",
        "targets.how.protein_lean", "targets.how.floor", "targets.pending_review",
        "protein.guide_lean", "protein.guide_adjusted", "home.cards.today_targets.title",
        "diary.disclaimer", "diary.eye.hide", "diary.eye.show", "diary.hidden_numbers",
        "settings.diary.title", "settings.diary.numbers.hide_all", "settings.diary.reset_confirm",
    ):  # fmt: skip
        for lang, value in _en_hi_mr(key):
            assert isinstance(value, str) and value, (lang, key)


BANNED = re.compile(
    r"\b(manage[sd]?|managing|treat(s|ed|ing|ment)?|cure[sd]?|curing|reverse[sd]?|"
    r"you need|diagnos\w*|prescri\w*|dose|dosage)\b",
    re.IGNORECASE,
)
BANNED_NATIVE = (
    "इलाज",
    "उपचार",
    "रोग मुक्त",
    "उलट",
    "आपको चाहिए",
    "खुराक",
    "डोस",
    "तुम्हाला हवे",
    "बरा करत",
)
# The carbohydrate reference minimum is a reference value from the spec, not a dose.
DOSE_EXEMPT = {"targets.flag.carbs_below_reference"}
NEW_ERRORS = (
    "goal_not_allowed_minor", "goal_not_allowed_underweight", "target_weight_too_low",
    "rate_not_allowed", "fat_pct_out_of_range", "adaptive_not_enabled", "body_fat_out_of_range",
    "diary_member_not_enabled", "date_in_future", "goal_settings_not_found",
)  # fmt: skip


def _flat(node, prefix=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from _flat(v, f"{prefix}{k}.")
    else:
        yield prefix[:-1], node


def _new_strings(lang: str):
    data = json.loads((MESSAGES / f"{lang}.json").read_text(encoding="utf-8"))
    for key, value in _flat(data):
        if (
            key.startswith(
                (
                    "targets.",
                    "diary.",
                    "settings.diary.",
                    "home.cards.today_targets.",
                    "methodology.section.energy_targets.",
                )
            )
            or key in ("protein.guide_lean", "protein.guide_adjusted")
            or key in {f"error.{c}" for c in NEW_ERRORS}
        ):
            yield key, value


def test_new_copy_has_no_medical_claims():
    for lang in ("en", "hi", "mr"):
        seen = list(_new_strings(lang))
        assert len(seen) > 80, lang
        for key, value in seen:
            assert not BANNED.search(value), (lang, key, value)
            for word in BANNED_NATIVE:
                assert word not in value, (lang, key, word)
            if key not in DOSE_EXEMPT:
                assert not re.search(r"\d+\s*(g|mg)\s*(per|a|/)\s*day", value, re.IGNORECASE), (
                    lang,
                    key,
                )


def test_no_support_contact_in_the_new_copy():
    # Q14: no support link or number anywhere.
    for lang in ("en", "hi", "mr"):
        for key, value in _new_strings(lang):
            assert not re.search(
                r"https?://|helpline|hotline|\b1800\b|\+91|tel:", value, re.IGNORECASE
            ), (lang, key)


def test_hi_and_mr_keys_match_en():
    def keys(lang):
        return {k for k, _ in _new_strings(lang)}

    assert keys("en") == keys("hi") == keys("mr")
    assert "targets.how.title" in keys("en") and "targets.how" not in keys("en")


def test_generator_reads_only_inputs():
    # a hand-edited expected file must be caught by --check
    new, old, tags = gen.changes()
    assert tags == {} and new == old
